#include <queue>
#include <unordered_set>
using namespace std;

class Solution {
public:
    int smallestRepunitDivByK(int K) {
        if (K % 2 == 0 || K % 5 == 0) return -1;

        queue<int> q;
        unordered_set<int> visited;
        q.push(1);
        visited.insert(1);

        int steps = 1;

        while (!q.empty()) {
            int num = q.front();
            q.pop();

            if (num % K == 0) return steps;

            num = (num * 10 + 1) % K;
            if (!visited.count(num)) {
                q.push(num);
                visited.insert(num);
            }

            steps++;
        }

        return -1;
    }
};
